/*
 * Sổ ôn certsafari: the team's purchased question sets with per-question analysis.
 * Data (window.CERTSAFARI) is LOCAL ONLY: generated by tools/import-certsafari.mjs into ccar-f/certsafari/data.js (git-ignored).
 * Uses window.CERT_DATA (ccar-f) for scenario names and for links to lessons by task statement.
 */
(function () {
  "use strict";
  var C = window.CCN, D = window.CERT_DATA, S = window.CERTSAFARI;
  var esc = C.esc, el = C.el, LET = C.LETTERS;
  var main = document.getElementById("cs-main"), side = document.getElementById("cs-side");
  document.getElementById("bar-title").textContent = "Sổ ôn certsafari · CCAR-F";

  if (!S) {
    main.innerHTML = '<section class="box"><h3>Chưa có dữ liệu trên máy này</h3>' +
      "<p>Sổ ôn certsafari là bộ đề team đã mua, nên dữ liệu chỉ nằm trên máy của từng người, không đưa lên trang công khai.</p>" +
      "<p>Để dùng: clone repo sổ ôn gốc về <code>~/claude-cert</code>, rồi trong thư mục site chạy:</p>" +
      "<pre><code>node tools/import-certsafari.mjs</code></pre><p>Sau đó mở trang này bằng file trên máy (<code>ccar-f/certsafari.html</code>).</p></section>";
    side.hidden = true;
    return;
  }

  var KEY = "ccarf-certsafari-v1";
  var answers = C.store.get(KEY, {}) || {};
  function save() { C.store.set(KEY, answers); }
  var UI_KEY = KEY + "-ui";
  var ui = C.store.get(UI_KEY, {}) || {};
  var view = ui.view || "de-" + Object.keys(S.exams)[0];
  var onlyFirstWrong = false;

  // ---- normalise entries into questions ----
  var all = S.entries.map(function (e) {
    var idx = e.answer.split("").map(function (ch) { return LET.indexOf(ch); });
    return {
      e: e, key: e.de + "-" + e.n,
      q: { q: e.ask, options: e.opts.map(function (o) { return o.gist; }), answer: idx.length > 1 ? idx : idx[0], ts: e.sub ? [e.sub] : [] },
      dom: e.sub ? +e.sub.split(".")[0] : 0,
      firstWrong: !!(e.first && e.first !== e.answer)
    };
  });
  var exams = Object.keys(S.exams).map(Number).sort(function (a, b) { return a - b; }).map(function (de) {
    return { de: de, label: S.exams[de], items: all.filter(function (x) { return x.e.de === de; }).sort(function (a, b) { return a.e.n - b.e.n; }) };
  });

  function stateOf(x) {
    var a = answers[x.key];
    if (!a || !a.length) return null;
    return C.sameSet(a, C.answerSet(x.q)) ? "right" : "wrong";
  }
  function examStats(ex) {
    var done = 0, right = 0;
    ex.items.forEach(function (x) { var s = stateOf(x); if (s) { done++; if (s === "right") right++; } });
    return { done: done, right: right };
  }
  function scenario(key) {
    if (!key || !D || !D.scenarios) return null;
    var id = key.toLowerCase();
    for (var i = 0; i < D.scenarios.length; i++) if (D.scenarios[i].id === id) return D.scenarios[i];
    return null;
  }
  function list(arr) {
    if (!arr || !arr.length) return "";
    return "<ul>" + arr.map(function (s) { return "<li>" + C.sanitize(s) + "</li>"; }).join("") + "</ul>";
  }

  // ---- sidebar ----
  function renderSide() {
    side.innerHTML = "";
    var sb = el("button", { type: "button", class: "cs-statbtn" + (view === "stats" ? " on" : ""), text: "Thống kê câu và domain hay sai" });
    sb.addEventListener("click", function () { go("stats"); });
    side.appendChild(sb);
    side.appendChild(el("p", { class: "cs-label", text: "Đề" }));
    exams.forEach(function (ex) {
      var st = examStats(ex), open = view === "de-" + ex.de;
      var d = el("details", { class: "cs-de" + (open ? " cur" : "") });
      if (open) d.setAttribute("open", "");
      d.innerHTML = '<summary><b>Đề ' + ex.de + '</b><span>' + ex.items.length + " câu · đúng " + st.right + "/" + st.done + "</span></summary>" +
        '<p class="hint">' + esc(ex.label) + "</p>";
      var grid = el("div", { class: "cs-grid" });
      ex.items.forEach(function (x) {
        var s = stateOf(x);
        var b = el("button", { type: "button", class: s || "", text: String(x.e.n) });
        b.addEventListener("click", function () { go("de-" + ex.de, x.key); });
        grid.appendChild(b);
      });
      d.appendChild(grid);
      d.querySelector("summary").addEventListener("click", function (ev) { ev.preventDefault(); go("de-" + ex.de); });
      side.appendChild(d);
    });
  }

  function go(v, focusKey) {
    view = v; ui.view = v; C.store.set(UI_KEY, ui);
    render();
    document.body.classList.remove("cs-drawer");
    if (focusKey) {
      var t = document.getElementById("cs-" + focusKey);
      if (t) t.scrollIntoView({ block: "start" });
    } else window.scrollTo(0, 0);
  }

  // ---- exam view ----
  function renderExam(ex) {
    var st = examStats(ex);
    main.innerHTML = "";
    var head = el("section", { class: "cs-head" });
    head.innerHTML = "<h1>Sổ ôn certsafari</h1>" +
      '<p class="hint">Bộ đề team đã mua (certsafari, Udemy), chia theo đề. Đề Udemy có khung kịch bản như đề thật. Bấm đáp án là biết đúng sai ngay ' +
      '(câu "Choose TWO" chấm khi chọn đủ hai), rồi bấm <b>Giải thích</b> để xem phân tích đề, từng phương án và bài cần đọc lại trong <a href="notes.html">bài học</a>. ' +
      "Đáp án đã chọn được giữ lại trên máy này. Dữ liệu chỉ có trên máy, không đưa lên trang công khai.</p>" +
      '<div class="cs-bar"><b>Đề ' + ex.de + " · " + esc(ex.label) + "</b><span>đã trả lời " + st.done + "/" + ex.items.length + " · đúng " + st.right + "</span>" +
      '<label class="hint"><input type="checkbox" id="cs-fw"' + (onlyFirstWrong ? " checked" : "") + "> Chỉ câu lần đầu làm sai</label>" +
      '<button type="button" class="btn ghost small" id="cs-reset">Làm lại cả đề</button></div>';
    main.appendChild(head);
    head.querySelector("#cs-fw").addEventListener("change", function () { onlyFirstWrong = this.checked; renderExam(ex); });
    head.querySelector("#cs-reset").addEventListener("click", function () {
      if (!confirm("Xóa các đáp án đã chọn của Đề " + ex.de + " và làm lại?")) return;
      ex.items.forEach(function (x) { delete answers[x.key]; });
      save(); render();
    });

    var items = ex.items.filter(function (x) { return !onlyFirstWrong || x.firstWrong; });
    if (!items.length) main.appendChild(el("p", { class: "hint", text: "Đề này không có câu nào lần đầu làm sai." }));
    var prevScen = null;
    items.forEach(function (x) {
      var e = x.e;
      if (e.scen && e.scen !== prevScen) {
        var sc = scenario(e.scen);
        var box = el("aside", { class: "scenario cs-scen" });
        box.innerHTML = "<p><b>Kịch bản " + esc(e.scen) + " · " + esc(sc ? sc.name : e.scen) + "</b></p>" + (sc ? "<p>" + esc(sc.desc) + "</p>" : "");
        main.appendChild(box);
      }
      prevScen = e.scen || null;
      main.appendChild(card(x));
    });
  }

  function analysis(x) {
    var e = x.e, right = C.answerSet(x.q);
    var opts = e.opts.map(function (o, i) {
      var ok = right.indexOf(i) !== -1;
      return '<div class="cs-opt ' + (ok ? "ok" : "no") + '"><b>' + LET[i] + (ok ? " · đúng" : " · sai") + "</b> " + C.sanitize(o.gist) + list(o.why) + "</div>";
    }).join("");
    var related = C.relatedLinks(D, x.q, "notes.html");
    return '<div class="cs-x">' +
      (e.scene && e.scene.length ? "<h4>Đề kể gì</h4>" + list(e.scene) : "") +
      (e.asks && e.asks.length ? "<h4>Đề hỏi gì</h4>" + list(e.asks) : "") +
      (e.facts && e.facts.length ? "<h4>Cần biết</h4>" + list(e.facts) : "") +
      "<h4>Từng phương án</h4>" + opts +
      (e.dispute ? '<div class="warn">' + C.sanitize(e.dispute) + "</div>" : "") +
      (e.first ? '<p class="hint">Lần đầu làm đề gốc đã chọn: <b>' + esc(e.first) + "</b>" + (x.firstWrong ? " (sai)" : " (đúng)") + "</p>" : "") +
      (related ? '<p class="qmeta">' + related + "</p>" : "") + "</div>";
  }

  function card(x) {
    var e = x.e;
    var c = el("section", { class: "box cs-card", id: "cs-" + x.key });
    var tag = e.sub ? '<span class="tag">' + esc(e.sub) + " " + esc(e.subName || "") + "</span>" : "";
    c.appendChild(el("p", { class: "hint cs-meta" }, "Câu " + e.n + "/" + e.total + " " + tag + (x.firstWrong ? ' <span class="badge warn">lần đầu sai</span>' : "")));
    var xbtn, xbox;
    var node = C.renderQuestion(x.q, {
      html: true, instant: true, retry: true,
      selected: answers[x.key] || [], reveal: !!(answers[x.key] && answers[x.key].length),
      onGrade: function (ok, sel) { answers[x.key] = sel; save(); renderSide(); updateBar(); showX(); },
      onReset: function () { delete answers[x.key]; save(); renderSide(); updateBar(); if (xbtn) { xbtn.remove(); xbtn = null; } if (xbox) { xbox.remove(); xbox = null; } }
    });
    c.appendChild(node);
    function showX() {
      if (xbtn) return;
      xbtn = el("button", { type: "button", class: "btn small", text: "Giải thích" });
      xbtn.addEventListener("click", function () {
        if (xbox) { xbox.remove(); xbox = null; xbtn.textContent = "Giải thích"; return; }
        xbox = el("div", null, analysis(x));
        c.appendChild(xbox);
        xbtn.textContent = "Ẩn giải thích";
      });
      node.querySelector(".qact").appendChild(xbtn);
    }
    if (answers[x.key] && answers[x.key].length) showX();
    return c;
  }

  function updateBar() {
    var bar = main.querySelector(".cs-bar span");
    if (!bar) return;
    var ex = exams.filter(function (e) { return "de-" + e.de === view; })[0];
    if (!ex) return;
    var st = examStats(ex);
    bar.textContent = "đã trả lời " + st.done + "/" + ex.items.length + " · đúng " + st.right;
  }

  // ---- stats view ----
  function renderStats() {
    main.innerHTML = "";
    var box = el("section", { class: "box" });
    var done = 0, right = 0;
    all.forEach(function (x) { var s = stateOf(x); if (s) { done++; if (s === "right") right++; } });
    var rows = exams.map(function (ex) {
      var st = examStats(ex);
      return "<tr><td>Đề " + ex.de + "</td><td>" + esc(ex.label) + "</td><td>" + st.done + "/" + ex.items.length + "</td><td>" + st.right + (st.done ? " (" + Math.round(st.right / st.done * 100) + "%)" : "") + "</td></tr>";
    }).join("");
    function bars(counter, labelOf) {
      var keys = Object.keys(counter).sort(function (a, b) { return counter[b] - counter[a]; });
      var max = Math.max.apply(null, keys.map(function (k) { return counter[k]; }).concat([1]));
      return keys.map(function (k) {
        return '<div class="dombar"><span>' + esc(labelOf(k)) + '</span><span class="pbar"><i class="lowv" style="width:' + (counter[k] / max * 100) + '%"></i></span><span>' + counter[k] + "</span></div>";
      }).join("") || '<p class="hint">Chưa có dữ liệu.</p>';
    }
    var mineDom = {}, mineTs = {}, firstDom = {}, firstTs = {};
    var subName = {};
    all.forEach(function (x) {
      subName[x.e.sub] = x.e.subName;
      if (stateOf(x) === "wrong") { mineDom[x.dom] = (mineDom[x.dom] || 0) + 1; mineTs[x.e.sub] = (mineTs[x.e.sub] || 0) + 1; }
      if (x.firstWrong) { firstDom[x.dom] = (firstDom[x.dom] || 0) + 1; firstTs[x.e.sub] = (firstTs[x.e.sub] || 0) + 1; }
    });
    var domLabel = function (k) { var d = D && D.domains[k - 1]; return "D" + k + (d ? " · " + d.name : ""); };
    var tsLabel = function (k) { return k + " " + (subName[k] || ""); };
    function top(counter, n) { var o = {}; Object.keys(counter).sort(function (a, b) { return counter[b] - counter[a]; }).slice(0, n).forEach(function (k) { o[k] = counter[k]; }); return o; }
    box.innerHTML = "<h3>Thống kê</h3>" +
      '<div class="score"><div class="stat"><div class="v">' + all.length + '</div><div class="k">câu trong ' + exams.length + " đề</div></div>" +
      '<div class="stat"><div class="v">' + done + '</div><div class="k">câu bạn đã làm ở đây</div></div>' +
      '<div class="stat"><div class="v">' + (done ? Math.round(right / done * 100) + "%" : "–") + '</div><div class="k">tỉ lệ đúng</div></div></div>' +
      '<div class="tablewrap"><table><thead><tr><th>Đề</th><th>Nguồn</th><th>Đã làm</th><th>Đúng</th></tr></thead><tbody>' + rows + "</tbody></table></div>" +
      "<h3>Bạn sai nhiều ở domain nào (trên trang này)</h3>" + bars(mineDom, domLabel) +
      "<h3>Task statement bạn hay sai (top 10)</h3>" + bars(top(mineTs, 10), tsLabel) +
      "<h3>Lần làm đầu trên đề gốc: domain hay sai</h3>" + bars(firstDom, domLabel) +
      "<h3>Lần làm đầu trên đề gốc: task statement hay sai (top 10)</h3>" + bars(top(firstTs, 10), tsLabel);
    main.appendChild(box);
  }

  function render() {
    renderSide();
    if (view === "stats") { renderStats(); return; }
    var ex = exams.filter(function (e) { return "de-" + e.de === view; })[0] || exams[0];
    view = "de-" + ex.de;
    renderExam(ex);
  }

  document.getElementById("cs-toggle").addEventListener("click", function () { document.body.classList.toggle("cs-drawer"); });
  render();
})();
